alter table public.email_campaigns add column signature_html text,add column signature_text text,add column delivery_state text,add column approved_revision timestamptz,add column approved_by uuid,add column approved_at timestamptz;
create table public.campaign_delivery_items(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.email_campaigns(id),campaign_revision timestamptz not null,contact_id uuid,company_id uuid,user_id uuid not null,mailbox text not null,recipient_email text not null,mode text not null,scheduled_at timestamptz not null,snapshot jsonb not null,snapshot_hash text not null,state text not null default 'pending',claim_token uuid,claimed_at timestamptz,finished_at timestamptz,budapest_day date,gmail_message_id text,email_id uuid,reason text,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),unique(campaign_id,campaign_revision,mailbox,recipient_email));
grant all on public.campaign_delivery_items to service_role;
revoke all on public.campaign_delivery_items from anon,authenticated;
alter table public.campaign_delivery_items enable row level security;
create index campaign_delivery_pending on public.campaign_delivery_items(campaign_id,state,scheduled_at);
create function public.campaign_delivery_guard() returns trigger language plpgsql set search_path=public as $$begin
 if current_user not in ('postgres','service_role') then raise exception 'Szerveroldali kampányművelet' using errcode='42501';end if;
 if new.mode not in ('test','customer') or new.state not in ('pending','claimed','verified','uncertain','blocked','cancelled') or new.mailbox not in ('info@vibateam.hu','ramon.dencsi@vibateam.hu','pretor.laszlo@vibateam.hu') or new.recipient_email !~ '^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$' or jsonb_typeof(new.snapshot) is distinct from 'object' or not(new.snapshot ?& array['subject','body','html']) or octet_length(new.snapshot::text)>250000 or new.snapshot_hash !~ '^[a-f0-9]{64}$' then raise exception 'Hibás kampánysor';end if;
 if new.mode='test' and new.recipient_email not in ('viktor.csotai@gmail.com','info@vibateam.hu') then raise exception 'Csak engedélyezett TESZT-cím';end if;
 if new.mode='customer' and (new.contact_id is null or new.company_id is null) then raise exception 'Ügyfélkapcsolat szükséges';end if;
 if tg_op='UPDATE' then
 if (new.campaign_id,new.campaign_revision,new.contact_id,new.company_id,new.user_id,new.mailbox,new.recipient_email,new.mode,new.scheduled_at,new.snapshot,new.snapshot_hash) is distinct from (old.campaign_id,old.campaign_revision,old.contact_id,old.company_id,old.user_id,old.mailbox,old.recipient_email,old.mode,old.scheduled_at,old.snapshot,old.snapshot_hash) then raise exception 'A jóváhagyott levélmásolat nem módosítható';end if;
 if old.state<>'pending' and new.state='pending' then raise exception 'Küldési kísérlet nem indítható újra';end if;
 if old.state in ('verified','uncertain','blocked','cancelled') and new.state is distinct from old.state then raise exception 'Lezárt eredmény';end if;
 end if;new.updated_at:=clock_timestamp();return new;end$$;
create trigger campaign_delivery_guard before insert or update on public.campaign_delivery_items for each row execute function public.campaign_delivery_guard();
create function public.campaign_delivery_campaign_guard() returns trigger language plpgsql set search_path=public as $$declare svc boolean:=current_user in ('postgres','service_role');changed boolean;begin
 if tg_op='INSERT' then changed:=new.signature_html is not null or new.signature_text is not null or new.delivery_state is not null or new.approved_revision is not null or new.approved_by is not null or new.approved_at is not null;
 else changed:=(new.signature_html,new.signature_text,new.delivery_state,new.approved_revision,new.approved_by,new.approved_at) is distinct from (old.signature_html,old.signature_text,old.delivery_state,old.approved_revision,old.approved_by,old.approved_at);end if;
 if changed and not svc then raise exception 'Védett kampánymentés szükséges' using errcode='42501';end if;
 if length(new.signature_html)>50000 or length(new.signature_text)>10000 or new.delivery_state not in ('scheduled','paused','stopped') then raise exception 'Hibás aláírás vagy ütemezés';end if;
 if tg_op='UPDATE' and (new.name,new.target_group,new.message_subject,new.message_body,new.message_html,new.signature_html,new.signature_text,new.gmail_draft_source,new.target_company_ids,new.status,new.prechecked_at) is distinct from (old.name,old.target_group,old.message_subject,old.message_body,old.message_html,old.signature_html,old.signature_text,old.gmail_draft_source,old.target_company_ids,old.status,old.prechecked_at) then
 new.approved_revision:=null;new.approved_by:=null;new.approved_at:=null;new.delivery_state:=null;
 end if;return new;end$$;
create trigger z_campaign_delivery_campaign_guard before insert or update on public.email_campaigns for each row execute function public.campaign_delivery_campaign_guard();
create function public.campaign_save_message(p_campaign uuid,p_user uuid,p_expected timestamptz,p_subject text,p_body text,p_html text,p_signature_html text,p_signature_text text) returns jsonb language plpgsql security invoker set search_path=public as $$declare c public.email_campaigns;r text;begin
 if current_user<>'service_role' then raise exception 'Szerveroldali művelet';end if;
 r:=public.crm_role_of(p_user);select * into c from public.email_campaigns where id=p_campaign for update;
 if not found or r is null or r not in ('owner','marketing') or c.status='archived' or (r='marketing' and c.created_by is distinct from p_user) or c.updated_at is distinct from p_expected or p_expected is null then raise exception 'A kampány megváltozott vagy nem szerkeszthető';end if;
 if c.gmail_draft_source is not null and (p_subject,p_body,p_html) is distinct from(c.message_subject,c.message_body,c.message_html) then raise exception 'A Gmail-forrást előbb külön válaszd le';end if;
 if length(p_subject)>500 or length(p_body)>20000 or length(p_html)>200000 or length(p_signature_html)>50000 or length(p_signature_text)>10000 then raise exception 'Túl hosszú üzenet';end if;
 update public.email_campaigns set message_subject=p_subject,message_body=p_body,message_html=p_html,signature_html=p_signature_html,signature_text=p_signature_text,status='draft',prechecked_at=null where id=p_campaign;
 insert into activities(user_id,action,details) values(p_user,'campaign_message_save',jsonb_build_object('campaign_id',p_campaign,'previous_revision',p_expected));
 return jsonb_build_object('campaign_id',p_campaign);end$$;
create function public.campaign_schedule(p_campaign uuid,p_user uuid,p_expected timestamptz,p_mailbox text,p_rows jsonb) returns jsonb language plpgsql security invoker set search_path=public as $$declare c public.email_campaigns;r text;item jsonb;n integer:=0;begin
 if current_user<>'service_role' then raise exception 'Szerveroldali művelet';end if;
 r:=public.crm_role_of(p_user);select * into c from public.email_campaigns where id=p_campaign for update;
 if not found or r is null or r not in ('owner','marketing') or c.status='archived' or (r='marketing' and c.created_by is distinct from p_user) or c.updated_at is distinct from p_expected or p_expected is null then raise exception 'A kampány megváltozott';end if;
 if not exists(select 1 from users_profile where auth_user_id=p_user and active and lower(gmail_email)=p_mailbox and nullif(gmail_auth_error,'') is null) then raise exception 'Nincs saját aktív postafiók';end if;
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 40 then raise exception '1–40 címzett választható';end if;
 for item in select value from jsonb_array_elements(p_rows) loop
 if (item->>'scheduled_at')::timestamptz<clock_timestamp() or nullif(btrim(item->'snapshot'->>'subject'),'') is null or (nullif(btrim(item->'snapshot'->>'body'),'') is null and nullif(btrim(item->'snapshot'->>'html'),'') is null) then raise exception 'Hiányos üzenet vagy elmúlt időpont';end if;
 if item->>'mode'='customer' and (c.prechecked_at is null or not exists(select 1 from email_campaign_recipients k join contacts ct on ct.id=k.contact_id join companies co on co.id=ct.company_id where k.campaign_id=p_campaign and k.selected is true and k.eligibility='ready' and k.contact_id=(item->>'contact_id')::uuid and ct.company_id=(item->>'company_id')::uuid and lower(btrim(ct.email))=item->>'recipient_email' and not coalesce(ct.email_invalid,false) and not coalesce(co.marketing_blocked,false))) then raise exception 'A címzett nem kész vagy tiltott';end if;
 if exists(select 1 from marketing_email_suppressions where email_norm=item->>'recipient_email' and blocked) then raise exception 'Tiltott címzett';end if;
 insert into campaign_delivery_items(campaign_id,campaign_revision,contact_id,company_id,user_id,mailbox,recipient_email,mode,scheduled_at,snapshot,snapshot_hash) values(p_campaign,p_expected,(item->>'contact_id')::uuid,(item->>'company_id')::uuid,p_user,p_mailbox,item->>'recipient_email',item->>'mode',(item->>'scheduled_at')::timestamptz,item->'snapshot',item->>'snapshot_hash');n:=n+1;
 end loop;
 update email_campaigns set delivery_state='scheduled',approved_revision=p_expected,approved_by=p_user,approved_at=clock_timestamp() where id=p_campaign;
 insert into activities(user_id,action,details) values(p_user,'campaign_schedule',jsonb_build_object('campaign_id',p_campaign,'revision',p_expected,'count',n,'mailbox',p_mailbox));return jsonb_build_object('stored',n,'revision',p_expected);end$$;
create function public.campaign_delivery_control(p_campaign uuid,p_user uuid,p_expected timestamptz,p_action text) returns jsonb language plpgsql security invoker set search_path=public as $$declare c public.email_campaigns;r text;begin
 if current_user<>'service_role' then raise exception 'Szerveroldali művelet';end if;
 r:=public.crm_role_of(p_user);select * into c from email_campaigns where id=p_campaign for update;
 if not found or r is null or r not in ('owner','marketing') or (r='marketing' and c.created_by is distinct from p_user) or c.updated_at is distinct from p_expected or p_expected is null then raise exception 'A kampány megváltozott';end if;
 if c.approved_revision is null or p_action not in ('pause','resume','stop') or (p_action='resume' and c.delivery_state<>'paused') or c.delivery_state='stopped' then raise exception 'Nincs folytatható ütemezés';end if;
 update email_campaigns set delivery_state=case p_action when 'pause' then 'paused' when 'resume' then 'scheduled' else 'stopped' end where id=p_campaign;
 if p_action='stop' then update campaign_delivery_items set state='cancelled',finished_at=clock_timestamp(),reason='Tulajdonosi/felhasználói leállítás' where campaign_id=p_campaign and state='pending';end if;
 insert into activities(user_id,action,details) values(p_user,'campaign_delivery_control',jsonb_build_object('campaign_id',p_campaign,'action',p_action));return jsonb_build_object('campaign_id',p_campaign);end$$;
create function public.campaign_delivery_claim(p_item uuid,p_user uuid,p_hash text) returns jsonb language plpgsql security invoker set search_path=public as $$declare a public.campaign_delivery_items;c public.email_campaigns;r text;n integer;d date;begin
 if current_user<>'service_role' then raise exception 'Szerveroldali művelet';end if;
 select * into a from campaign_delivery_items where id=p_item;
 if not found or a.user_id is distinct from p_user then raise exception 'Nincs saját kampánysor';end if;
 select * into c from email_campaigns where id=a.campaign_id for update;
 select * into a from campaign_delivery_items where id=p_item for update;
 r:=crm_role_of(p_user);
 if r is null or r not in ('owner','marketing') or (r='marketing' and c.created_by is distinct from p_user) or c.status='archived' or c.delivery_state<>'scheduled' or c.approved_revision is distinct from a.campaign_revision or c.approved_by is distinct from p_user or a.state<>'pending' or a.scheduled_at>clock_timestamp() or a.snapshot_hash is distinct from p_hash then raise exception 'A kampánysor nem indítható';end if;
 if not exists(select 1 from users_profile where auth_user_id=p_user and active and lower(gmail_email)=a.mailbox and nullif(gmail_auth_error,'') is null) then raise exception 'Nincs saját aktív postafiók';end if;
 perform pg_advisory_xact_lock(hashtextextended('marketing-email:'||a.recipient_email,0));
 if exists(select 1 from marketing_email_suppressions where email_norm=a.recipient_email and blocked) or (a.mode='customer' and not exists(select 1 from contacts k join companies co on co.id=k.company_id join email_campaign_recipients e on e.contact_id=k.id and e.campaign_id=c.id where k.id=a.contact_id and k.company_id=a.company_id and lower(btrim(k.email))=a.recipient_email and not coalesce(k.email_invalid,false) and not coalesce(co.marketing_blocked,false) and e.selected is true and e.eligibility='ready')) then
 update campaign_delivery_items set state='blocked',reason='Friss cím/cég/alkalmassági ellenőrzés tiltja',finished_at=clock_timestamp() where id=p_item;return jsonb_build_object('claimed',false,'state','blocked');end if;
 perform pg_advisory_xact_lock(hashtextextended('campaign-mailbox:'||a.mailbox,0));d:=(clock_timestamp() at time zone 'Europe/Budapest')::date;
 select (select count(*) from campaign_send_audit where mailbox=a.mailbox and budapest_day=d)+(select count(*) from campaign_delivery_items where mailbox=a.mailbox and budapest_day=d and claimed_at is not null) into n;
 if n>=40 then raise exception 'A napi 40 kampánylevél keret elfogyott';end if;
 update campaign_delivery_items set state='claimed',claim_token=gen_random_uuid(),claimed_at=clock_timestamp(),budapest_day=d where id=p_item returning * into a;
 insert into activities(user_id,action,details) values(p_user,'campaign_delivery_claim',jsonb_build_object('campaign_id',a.campaign_id,'item_id',a.id));return jsonb_build_object('claimed',true,'token',a.claim_token);end$$;
create function public.campaign_delivery_finish(p_item uuid,p_user uuid,p_token uuid,p_gmail text,p_email uuid,p_verified boolean) returns jsonb language plpgsql security invoker set search_path=public as $$declare a public.campaign_delivery_items;valid boolean;begin
 if current_user<>'service_role' then raise exception 'Szerveroldali művelet';end if;
 select * into a from campaign_delivery_items where id=p_item and user_id=p_user and claim_token=p_token for update;
 if not found or a.state<>'claimed' then raise exception 'Nincs lezárható saját foglalás';end if;
 valid:=coalesce(p_verified,false) and exists(select 1 from emails e where e.id=p_email and e.owner_user_id=p_user and e.gmail_message_id=p_gmail and lower(e.from_email)=a.mailbox and e.to_emails=array[a.recipient_email] and coalesce(cardinality(e.cc_emails),0)=0 and coalesce(cardinality(e.bcc_emails),0)=0 and e.gmail_label_ids @> array['SENT'] and not e.gmail_label_ids && array['DRAFT','SPAM','TRASH'] and e.subject=a.snapshot->>'subject' and e.body=a.snapshot->>'html' and e.company_id is not distinct from a.company_id and e.contact_id is not distinct from a.contact_id);
 update campaign_delivery_items set state=case when valid then 'verified' else 'uncertain' end,gmail_message_id=p_gmail,email_id=p_email,finished_at=clock_timestamp() where id=p_item;
 insert into activities(user_id,action,details) values(p_user,'campaign_delivery_finish',jsonb_build_object('item_id',p_item,'verified',valid));return jsonb_build_object('state',case when valid then 'verified' else 'uncertain' end);end$$;
revoke all on function public.campaign_save_message(uuid,uuid,timestamptz,text,text,text,text,text),public.campaign_schedule(uuid,uuid,timestamptz,text,jsonb),public.campaign_delivery_control(uuid,uuid,timestamptz,text),public.campaign_delivery_claim(uuid,uuid,text),public.campaign_delivery_finish(uuid,uuid,uuid,text,uuid,boolean) from public,anon,authenticated;
grant execute on function public.campaign_save_message(uuid,uuid,timestamptz,text,text,text,text,text),public.campaign_schedule(uuid,uuid,timestamptz,text,jsonb),public.campaign_delivery_control(uuid,uuid,timestamptz,text),public.campaign_delivery_claim(uuid,uuid,text),public.campaign_delivery_finish(uuid,uuid,uuid,text,uuid,boolean) to service_role;
-- Preserve the existing TESZT claim, adding only shared quota accounting.
do $$declare definition text;begin select pg_get_functiondef(oid) into definition from pg_proc where pronamespace='public'::regnamespace and proname='campaign_test_claim';if definition is null then raise exception 'Missing prior test claim';end if;definition:=replace(definition,'select count(*) into n from public.campaign_send_audit where mailbox=sender and budapest_day=d;','select (select count(*) from public.campaign_send_audit where mailbox=sender and budapest_day=d)+(select count(*) from public.campaign_delivery_items where mailbox=sender and budapest_day=d and claimed_at is not null) into n;');execute definition;end$$;